      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<integer>;
  var currentGroup := new StringBuilder;
  var groups := new List<string>;
  var ignoreSpaces := parenString.Replace(' ', '');

  for var i := 1 to ignoreSpaces.Length do
  begin
    var ch := ignoreSpaces[i];

    if ch = '(' then
    begin
      if currentGroup.Length > 0 then
        groups.Add(currentGroup.ToString);
        currentGroup.Clear;
      stack.Push(i);
    end
    else if ch = ')' then
    begin
      currentGroup.Append(ch);
      var start := stack.Pop;
      var endIndex := i;

      while stack.Count > 0 do
      begin
        endIndex := stack.Pop;
        currentGroup.Append(ignoreSpaces[endIndex]);
      end;

      groups.Add(currentGroup.ToString);
      currentGroup.Clear;
    end;
  end;

  Result := groups.ToArray;
end;


