function FindClosestElements(numbers: array of real): (real, real);
begin
  if numbers.Length < 2 then
  begin
    Result := (0, 0);
    exit;
  end;

  &Array.Sort(numbers);
  var minDiff := real.MaxValue;
  var closestPair := (0, 0);

  for var i := 0 to numbers.Length - 2 do
  begin
    var diff := Abs(numbers[i] - numbers[i + 1]);
    if diff < minDiff then
    begin
      minDiff := diff;
      closestPair := (numbers[i], numbers[i + 1]);
    end;
  end;

  Result := closestPair;
end;


function RescaleToUnit(numbers : array of real): array of real;
begin
  if numbers.Length < 2 then
    raise new System.ArgumentException('Need at least two numbers');
  var minNum := numbers.Min;
  var maxNum := numbers.Max;
  var range := maxNum - minNum;
  Result := new real[numbers.Length];
  for var i := 0 to numbers.Length - 1 do
    Result[i] := (numbers[i] - minNum) / range;
end;


