function SortEven(l: array of integer): array of integer;
begin
  var even := new List<integer>;
  var odd := new List<integer>;

  for var i := 0 to l.Length - 1 do
    if i mod 2 = 0 then
      even.Add(l[i])
    else
      odd.Add(l[i]);

  even.Sort;

  var res := new integer[l.Length];
  var evenIndex := 0;

  for var i := 0 to l.Length - 1 do
    if i mod 2 = 0 then
    begin
      res[i] := even[evenIndex];
      evenIndex += 1;
    end
    else
      res[i] := odd[i - evenIndex];

  Result := res;
end;

function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;
begin
  var fib := new integer[n + 1];
  var prime := new boolean[n + 1];

  prime[0] := True;
  prime[1] := True;

  for var i := 2 to n do
  begin
    if prime[i] then
    begin
      fib[i] := fib[i - 1] + fib[i - 2];
      for var j := 2 * i to n step i do
        prime[j] := False;
    end;
  end;

  Result := fib[n];
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;

  for var i := 0 to sorted.Length - 3 do
  begin
    var left := i + 1;
    var right := sorted.Length - 1;

    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];

      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;

  Result := False;
end;


