function CorrectBracketing(brackets: string): boolean;
begin
  var st := new Stack<char>;
  foreach var ch in brackets do
  begin
    if ch = '<' then
      st.Push(ch)
    else if (st.Count > 0) and (st.Peek = '<') then
      st.Pop
    else
    begin
      Result := False;
      exit;
    end;
  end;
  Result := st.Count = 0;
end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length < 2 then
  begin
    Result := True;
    exit;
  end;

  var increasing := True;
  var decreasing := True;

  for var i := 0 to l.Length - 2 do
  begin
    if l[i] < l[i + 1] then
      decreasing := False
    else if l[i] > l[i + 1] then
      increasing := False;
  end;

  Result := increasing or decreasing;
end;


