function LargestPrimeFactor(n: integer): integer;
begin
  var largestPrime := 1;
  var i := 2;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      n := n div i;
      if i > largestPrime then
        largestPrime := i;
    end;
    i += 1;
  end;
  if n > 1 then
    if n > largestPrime then
      largestPrime := n;
  Result := largestPrime;
end;


