function CorrectBracketing(brackets: string): boolean;
begin
  var st := new Stack<char>;
  foreach var ch in brackets do
  begin
    if ch in ['(', '{', '['] then
      st.Push(ch)
    else if (ch in [')', '}', ']']) and (st.Count = 0) then
    begin
      Result := False;
      exit;
    end;
    if (ch in [')', '}', ']']) and (st.Count > 0) then
    begin
      var top := st.Pop;
      if (ch = ')') and (top <> '(') then begin Result := False; exit; end;
      if (ch = '}') and (top <> '{') then begin Result := False; exit; end;
      if (ch = ']') and (top <> '[') then begin Result := False; exit; end;
    end;
  end;
  Result := st.Count = 0;
end;


function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n < 2 then
    Result := new real[0]
  else
  begin
    var res := new real[n - 1];
    for var i := 1 to n - 1 do
      res[i - 1] := xs[i] * i;
    Result := res;
  end;
end;


