  var smallestIndex := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] < smallestEvenValue) then
    begin
      smallestEvenValue := arr[i];
      smallestIndex := i;
    end;
  end;

  if smallestIndex = -1 then
    Result := new integer[0]
  else
    Result := |smallestEvenValue, smallestIndex|;
end;


