function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;

  for var i := 2 to a - 1 do
  begin
    var isPrime := True;
    for var j := 2 to i - 1 do
      if i mod j = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primes.Add(i);
  end;

  var primeCount := primes.Count;

  for var i := 0 to primeCount - 1 do
    for var j := i + 1 to primeCount - 1 do
      for var k := j + 1 to primeCount - 1 do
        if primes[i] * primes[j] * primes[k] = a then
        begin
          Result := True;
          exit;
        end;

  Result := False;
end;


