function DecimalToBinary(decimal: integer): string;
begin
  if decimal = 0 then
  begin
    Result := '0';
    exit;
  end;

  var binary := '';
  while decimal > 0 do
  begin
    if decimal mod 2 = 0 then
      binary := '0' + binary
    else
      binary := '1' + binary;
    decimal := decimal div 2;
  end;

  Result := 'db' + binary + 'db';
end;


