function Encode(message: string): string;
begin
  var vowels := new HashSet<char>('aeiou'.ToCharArray);
  var sb := new StringBuilder;

  for var i := 1 to message.Length do
  begin
    var c := message[i];
    if c.IsLetter then
    begin
      if c.IsLower then
        sb.Append(Char.ToUpper(c))
      else
        sb.Append(Char.ToLower(c));

      if vowels.Contains(Char.ToLower(c)) then
        sb.Append(Chr(Ord(Char.ToLower(c)) + 2))
      else
        sb.Append(c);
    end
    else
      sb.Append(c);
  end;

  Result := sb.ToString;
end;


