function CountUpTo(n: integer): array of integer;
begin
  if n <= 1 then
  begin
    Result := new integer[0];
    exit;
  end;

  var primes := new List<integer>;
  primes.Add(2);

  for var i := 3 to n - 1 do
  begin
    var isPrime := True;
    foreach var p in primes do
    begin
      if p * p > i then
        break;
      if i mod p = 0 then
      begin
        isPrime := False;
        break;
      end;
    end;
    if isPrime then
      primes.Add(i);
  end;

  Result := primes.ToArray;
end;


