function Histogram(test: string): Dictionary<string, integer>;
begin
  if test = '' then
  begin
    Result := new Dictionary<string, integer>;
    exit;
  end;

  var parts := test.Split(' ');
  var maxCount := 0;
  var maxLetters := new List<string>;

  foreach var letter in parts do
  begin
    var count := 0;
    for var i := 1 to letter.Length do
      if letter[i] = 'a' then
        count += 1;

    if count > maxCount then
    begin
      maxCount := count;
      maxLetters.Clear;
      maxLetters.Add(letter);
    end
    else if count = maxCount then
      maxLetters.Add(letter);
  end;

  Result := new Dictionary<string, integer>;
  for var i := 0 to maxLetters.Count - 1 do
    Result.Add(maxLetters[i], maxCount);
end;


