function GetClosestVowel(word: string): string;
begin
  var vowels := 'aeiouAEIOU';
  var lastVowel := #0;
  for var i := word.Length - 1 downto 1 do
  begin
    if vowels.Contains(word[i]) then
    begin
      if lastVowel = #0 then
        Result := word[i]
      else
      begin
        var distance := Abs(Ord(word[i]) - Ord(lastVowel));
        var nextDistance := Abs(Ord(word[i]) - Ord(word[i - 1]));
        if distance < nextDistance then
          Result := word[i]
        else
          lastVowel := word[i];
      end;
    end;
  end;
  Result := '';
end;


function MatchParens(lst: array of string): string;
begin
  var s := lst[0] + lst[1];
  var st := new Stack<char>;
  foreach var ch in s do
  begin
    if (ch = '(') or (st.Count = 0) then
      st.Push(ch)
    else if (ch = ')') and (st.Peek = '(') then
      st.Pop
    else
    begin
      Result := 'No';
      exit;
    end;
  end;
  Result := (st.Count = 0) ? 'Yes' : 'No';
end;


