function ValidDate(date: string): boolean;
begin
  var dateParts := date.Split('-');

  if dateParts.Length <> 3 then
  begin
    Result := False;
    exit;
  end;

  var month := integer.Parse(dateParts[0]);
  var day := integer.Parse(dateParts[1]);
  var year := integer.Parse(dateParts[2]);

  if (month < 1) or (month > 12) then
  begin
    Result := False;
    exit;
  end;

  if (day < 1) or (day > 31) then
  begin
    Result := False;
    exit;
  end;

  if month = 2 then
  begin
    if (day < 1) or (day > 29) then
    begin
      Result := False;
      exit;
    end;
  end
  else if (month = 4) or (month = 6) or (month = 9) or (month = 11) then
  begin
    if (day < 1) or (day > 30) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;


