function Intersection(interval1, interval2: array of integer): string;
begin
  var start := Max(interval1[0], interval2[0]);
  var endVal := Min(interval1[1], interval2[1]);

  if start > endVal then
    Result := 'NO'
  else if IsPrime(endVal - start + 1) then
    Result := 'YES'
  else
    Result := 'NO';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var prod := 1;
  foreach var x in arr do
    if x < 0 then
      prod := -prod;

  Result := Abs(prod) * arr.Sum(x -> Abs(x));
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var N := grid.Length;
  var ans := new integer[k];
  var visited := new boolean[N, N];
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));

  while queue.Count > 0 do
  begin
    var (x, y, c) := queue.Dequeue;
    if c = k then
    begin
      ans[c - 1] := grid[x][y];
      continue;
    end;

    var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;

      if (nx < 0) or (nx >= N) or (ny < 0) or (ny >= N) or visited[nx, ny] then
        continue;

      visited[nx, ny] := true;
      queue.Enqueue((nx, ny, c + 1));
    end;
  end;

  Result := ans;
end;


function Tri(n: integer): array of real;
begin
  if n = 0 then
  begin
    Result := new real[1];
    Result[0] := 3;
    exit;
  end;

  var trib := new real[n + 1];
  trib[0] := 3;

  if n > 0 then
    trib[1] := 1 + n / 2;

  if n > 1 then
    trib[2] := trib[0] + trib[1] + trib[2];

  for var i := 3 to n do
    trib[i] := trib[i - 1] + trib[i - 2] + trib[i - 3];

  Result := trib;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
      product *= digit;
    n := n div 10;
  end;
  Result := product;
end;


function IsNested(s: string): boolean;
begin
  var st := new Stack<char>;
  foreach var ch in s do
  begin
    if (ch = '[') or (ch = '{') or (ch = '(') then
      st.Push(ch)
    else if (ch = ']') or (ch = '}') or (ch = ')') then
    begin
      if st.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      var top := st.Pop;
      if (ch = ']') and (top <> '[') then begin Result := False; exit; end;
      if (ch = '}') and (top <> '{') then begin Result := False; exit; end;
      if (ch = ')') and (top <> '(') then begin Result := False; exit; end;
    end;
  end;
  Result := st.Count = 0;
end;


