function CanArrange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var maxIndex := -1;

  for var i := n - 2 downto 0 do
  begin
    if arr[i] < arr[i + 1] then
    begin
      maxIndex := i;
      break;
    end;
  end;

  Result := maxIndex;
end;


function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var largestNegative := integer.MinValue;
  var smallestPositive := integer.MaxValue;

  foreach var num in lst do
  begin
    if num < 0 then
      if num <> largestNegative then
        largestNegative := num;
    else if num > 0 then
      if num <> smallestPositive then
        smallestPositive := num;
  end;

  Result := (largestNegative, smallestPositive);
end;


function CompareOne(a, b: object): object;
begin
  if (a = nil) or (b = nil) then
    Result := nil
  else if (a is integer) and (b is integer) then
    Result := integer(a) > integer(b) ? a : b
  else if (a is real) and (b is real) then
    Result := real(a) > real(b) ? a : b
  else if (a is string) and (b is string) then
  begin
    var aVal := real(a);
    var bVal := real(b);
    if aVal.ToString.Contains(',') then
      aVal := real(System.Convert.ToDouble(aVal.ToString.Replace(',', '.')));
    if bVal.ToString.Contains(',') then
      bVal := real(System.Convert.ToDouble(bVal.ToString.Replace(',', '.')));
    Result := aVal > bVal ? a : b;
  end
  else
    Result := nil;
end;


