function SpecialFactorial(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
  begin
    var fact := 1bi;
    for var i := 1 to n do
      fact *= i;
    Result := fact * SpecialFactorial(n - 1);
  end;
end;


function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var prevSpace := #0;

  for var i := 1 to text.Length do
  begin
    var ch := text[i];

    if ch = ' ' then
    begin
      if prevSpace = #0 then
        sb.Append(ch)
      else
      begin
        if prevSpace = ' ' then
          sb.Append('_')
        else
          sb.Append('-');
        sb.Append(ch);
      end;
    end
    else
      sb.Append(ch);

    prevSpace := ch;
  end;

  Result := sb.ToString;
end;


function FileNameCheck(fileName: string): string;
begin
  if fileName.Length > 3 then
  begin
    Result := 'No';
    exit;
  end;

  var parts := fileName.Split('.');

  if parts.Length <> 2 then
  begin
    Result := 'No';
    exit;
  end;

  var nameParts := parts[0].Split(' ');

  if nameParts.Length = 0 then
  begin
    Result := 'No';
    exit;
  end;

  var firstLetter := nameParts[0][1];
  if not (Char.IsLower(firstLetter) or Char.IsUpper(firstLetter)) then
  begin
    Result := 'No';
    exit;
  end;

  for var i := 1 to nameParts.Length - 1 do
  begin
    if nameParts[i].Length = 0 then
    begin
      Result := 'No';
      exit;
    end;

    var lastLetter := nameParts[i][nameParts[i].Length];
    if not (Char.IsLower(lastLetter) or Char.IsUpper(lastLetter)) then
    begin
      Result := 'No';
      exit;
    end;
  end;

  var extension := parts[1].ToLower;
  if extension <> 'txt' then
  begin
    Result := 'No';
    exit;
  end;

  Result := 'Yes';
end;


function SumSquares(lst: array of integer): integer;
begin
  var sum := 0;

  for var i := 0 to lst.Length - 1 do
  begin
    if i mod 3 = 0 then
      sum += lst[i] * lst[i]
    else if i mod 4 = 0 then
      sum += lst[i] * lst[i] * lst[i];
  end;

  Result := sum;
end;


function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := new List<string>;

  foreach var word in words do
  begin
    var length := word.Length;
    var isPrime := True;

    for var i := 2 to &Round(Sqrt(length)) do
      if length mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primeWords.Add(word);
  end;

  Result := string.Join(' ', primeWords);
end;


function Simplify(x, n: string): boolean;
begin
  var xNum := integer.Parse(x.Split('/')[0]);
  var xDenom := integer.Parse(x.Split('/')[1]);
  var nNum := integer.Parse(n.Split('/')[0]);
  var nDenom := integer.Parse(n.Split('/')[1]);

  Result := (xNum * nDenom) = (nNum * xDenom);
end;


