function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;

  var count := 0;
  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          count += 1;

  Result := count;
end;


function Bf(planet1, planet2: string): array of string;
begin
  var planets := new List<string>;
  planets.AddRange(Arr('Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'));

  var idx1 := -1;
  for var i := 0 to 7 do
    if planets[i] = planet1 then
      idx1 := i;

  var idx2 := -1;
  for var i := 0 to 7 do
    if planets[i] = planet2 then
      idx2 := i;

  if idx1 = -1 then
  begin
    Result := new string[0];
    exit;
  end;

  if idx2 = -1 then
  begin
    Result := new string[0];
    exit;
  end;

  if idx1 > idx2 then
  begin
