      Result := True;
      exit;
    end;
  end;

  Result := False;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var absNum := Abs(num);

  while absNum > 0 do
  begin
    var digit := absNum mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    absNum := absNum div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  if number < 1 then
    Result := ''
  else
  begin
    var roman := new Dictionary<integer, string>;
    roman[1000] := 'm';
    roman[900] := 'cm';
    roman[500] := 'd';
    roman[400] := 'cd';
    roman[100] := 'c';
    roman[90] := 'xc';
    roman[50] := 'l';
    roman[40] := 'xl';
    roman[10] := 'x';
    roman[9] := 'ix';
    roman[5] := 'v';
    roman[4] := 'iv';
    roman[1] := 'i';

    var resultStr := '';
    var remaining := number;

    foreach var k in roman.Keys do
    begin
      var count := remaining div k;
      remaining := remaining mod k;

      if count > 0 then
        resultStr += roman[k] * count;
    end;

    Result := resultStr.ToLower;
  end;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  if (a * a + b * b = c * c) or (a * a + c * c = b * b) or (b * b + c * c = a * a) then
    Result := True
  else
    Result := False;
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    var numUnique := uniqueChars.Count;

    if numUnique > maxUnique then
    begin
      maxUnique := numUnique;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
    Result := (number + need, remaining - need)
  else
    Result := (number + remaining, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  if op.Length < operand.Length - 1 then
    raise new System.ArgumentException('Operator list length is not equal to operand list length minus one.');

  if op.Length = 0 then
    raise new System.ArgumentException('Operator list is empty.');

  if operand.Length = 0 then
    raise new System.ArgumentException('Operand list is empty.');

  var res := operand[0];

  for var i := 0 to op.Length - 1 do
  begin
    case op[i] of
      '+': res += operand[i + 1];
      '-': res -= operand[i + 1];
      '*': res *= operand[i + 1];
      '//': res := integer(res div operand[i + 1]);
      '**': res := integer(Power(res, operand[i + 1]));
      else raise new System.ArgumentException('Unknown operator: ' + op[i]);
    end;
  end;

  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in s do
    if Char.IsLetter(ch) then
      if Char.IsLower(ch) then
        sb.Append(Char.ToUpper(ch))
      else
        sb.Append(Char.ToLower(ch));
    else
      sb.Append(ch);
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if string.IsNullOrEmpty(text) then
  begin
    Result := nil;
    exit;
  end;

  var md5 := System.Security.Cryptography.MD5.Create;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);

  Result := hash.Select(b -> b.ToString('x2')).JoinToString('');
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  if a > b then Swap(a, b);
  var res := new integer[a mod 2 + 1];
  var idx := 0;
  for var i := a to b step 2 do
  begin
    res[idx] := i;
    idx += 1;
  end;
  Result := res;
end;
